import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { GAME_URL, PHONE, exportedSnapshot, loadFixedBoard, moves } from './game-fixture.ts';

test('finishes the literal board by keyboard without inspecting hidden faces', async ({ page }) => {
  await loadFixedBoard(page);
  await expect(page.locator('.card.closed svg'), 'I14 hidden cards mount no face').toHaveCount(0);
  await expect(page.locator('[data-face], [data-face-id]')).toHaveCount(0);
  for (const pair of EXAMPLE_PAIRS) {
    for (const index of pair) {
      await page.locator('.card').first().focus();
      for (let row = 0; row < Math.floor(index / 4); row += 1)
        await page.keyboard.press('ArrowDown');
      for (let column = 0; column < index % 4; column += 1) await page.keyboard.press('ArrowRight');
      await page.keyboard.press('Enter');
    }
  }
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await moves(page)).toBe(8);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
  expect(await page.locator('.victory').count()).toBe(1);
  const first = await exportedSnapshot(page);
  const second = await exportedSnapshot(page);
  expect(second.elapsedMs).toBe(first.elapsedMs);
});

test('finishes by phone taps with visible 44px targets', async ({ browser }) => {
  const context = await browser.newContext({ viewport: PHONE, isMobile: true, hasTouch: true });
  try {
    const page = await context.newPage();
    await loadFixedBoard(page);
    const bounds = await page.locator('.card').first().boundingBox();
    expect(bounds?.width).toBeGreaterThanOrEqual(44);
    expect(bounds?.height).toBeGreaterThanOrEqual(44);
    for (const pair of EXAMPLE_PAIRS)
      for (const index of pair) await page.locator('.card').nth(index).tap();
    await expect(page.locator('.card.matched')).toHaveCount(16);
    expect(await moves(page)).toBe(8);
  } finally {
    await context.close();
  }
});

test('loads the built file with the network offline and no external requests', async ({
  context,
  page,
}) => {
  const requested: string[] = [];
  page.on('request', (request) => {
    requested.push(request.url());
  });
  await context.setOffline(true);
  await page.goto(GAME_URL);
  await expect(page.locator('.card')).toHaveCount(16);
  await page.locator('.card').first().click();
  await expect(page.locator('.card.revealed')).toHaveCount(1);
  expect(requested).toEqual([GAME_URL]);
});

test('keeps navigation focus at the board edges and leaves the board with Tab', async ({
  page,
}) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.first().focus();
  await page.keyboard.press('ArrowLeft');
  await expect(cards.first()).toBeFocused();
  await page.keyboard.press('ArrowUp');
  await expect(cards.first()).toBeFocused();
  // A 4x4 row or column takes three presses, so the fourth tests the edge.
  for (let step = 0; step < 4; step += 1) await page.keyboard.press('ArrowRight');
  await expect(cards.nth(3)).toBeFocused();
  for (let step = 0; step < 4; step += 1) await page.keyboard.press('ArrowDown');
  await expect(cards.last()).toBeFocused();
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  expect(await moves(page)).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { boardCode, parseBoardCode } from '../src/game/deck.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';
import type { Page } from '@playwright/test';

const SIZE = 16;
// Row 7, column 11 sits past the right edge of a phone board scrolled back to its start.
const REMEMBERED = 6 * SIZE + 10;
// Row 15, column 16 sits past the right and bottom edges of that board.
const FAR = 14 * SIZE + 15;
const EXAMPLE_SIZE = parseBoardCode(EXAMPLE_CODE)?.size ?? 0;

async function scrollBoardToStart(page: Page): Promise<void> {
  await page.locator('.board-viewport').evaluate((viewport) => viewport.scrollTo(0, 0));
  await page.evaluate(() => new Promise((ready) => requestAnimationFrame(ready)));
}

test('Tab and Shift+Tab bring the remembered card in with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const restart = page.getByRole('button', { name: DealControl.restart, exact: true });
  await restart.focus();
  await page.keyboard.press('Tab');
  await moveKeyboardTo(page, REMEMBERED, SIZE);
  const card = page.locator('.card').nth(REMEMBERED);
  for (const enter of ['Shift+Tab', 'Tab']) {
    if (enter === 'Shift+Tab') await page.keyboard.press('Tab');
    else await restart.focus();
    await scrollBoardToStart(page);
    await page.keyboard.press(enter);
    await expect(card).toBeFocused();
    const gaps = await boardGaps(card);
    expect(gaps.right, `I13 ${enter} enters with nearest alignment`).toBeCloseTo(gaps.margin, 0);
  }
});

test('Resume returns focus to the remembered card with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.locator('summary').click();
  const paused = {
    version: SNAPSHOT_VERSION,
    boardCode: boardCode(SIZE, 1),
    matched: [],
    selection: { kind: SelectionKind.one, index: 0 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(paused));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('.card').first().focus();
  await moveKeyboardTo(page, FAR, SIZE);
  const card = page.locator('.card').nth(FAR);
  await expect(card).toBeFocused();
  await scrollBoardToStart(page);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  expect(gaps.right, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
  expect(gaps.bottom, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
});

test('every keyboard move after a pointer click shows the focus outline', async ({ page }) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).click();
  for (const [key, index] of [
    ['ArrowRight', 6],
    ['ArrowDown', 6 + EXAMPLE_SIZE],
    ['ArrowLeft', 5 + EXAMPLE_SIZE],
    ['ArrowUp', 5],
  ] as const) {
    await page.keyboard.press(key);
    await expect(cards.nth(index)).toBeFocused();
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-style', 'solid');
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-width', '3px');
  }
});
import { expect, test } from './browser-test.ts';
import { finishBoard, loadFixedBoard } from './game-fixture.ts';

test('card transitions use 120ms and a completed game has one 600ms pulse', async ({ page }) => {
  await loadFixedBoard(page);
  const transitions = await page
    .locator('.card')
    .first()
    .evaluate((element) => {
      const style = getComputedStyle(element);
      return { duration: style.transitionDuration, property: style.transitionProperty };
    });
  expect(transitions.duration.split(',').every((duration) => parseFloat(duration) === 0.12)).toBe(
    true,
  );
  expect(transitions.property.split(',').map((value) => value.trim())).toEqual(['border-color']);
  await finishBoard(page);
  const pulse = await page.locator('.victory').evaluate((element) => {
    const style = getComputedStyle(element);
    return { duration: style.animationDuration, iterations: style.animationIterationCount };
  });
  expect(parseFloat(pulse.duration)).toBe(0.6);
  expect(Number(pulse.iterations)).toBe(1);
});

test('reduced motion removes card transitions and completion animation', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await loadFixedBoard(page);
  await finishBoard(page);
  expect(
    await page.locator('.victory').evaluate((element) => getComputedStyle(element).animationName),
  ).toBe('none');
  expect(
    parseFloat(
      await page
        .locator('.card')
        .first()
        .evaluate((element) => getComputedStyle(element).transitionDuration),
    ),
  ).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import {
  GAME_URL,
  exportedSnapshot,
  loadFixedBoard,
  loadTimedBoard,
  finishBoard,
} from './game-fixture.ts';

test('pauses elapsed time and a mismatch while the document is hidden', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(200);
  // Headless Chromium leaves every tab visible, so control this browser input at the adapter.
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  const before = await exportedSnapshot(page);
  await page.clock.runFor(2000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(before.elapsedMs);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(599);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

test('continues playing when access to browser storage is denied', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', {
      get: () => {
        throw new DOMException('Blocked', 'SecurityError');
      },
    });
  });
  await loadFixedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.card.matched')).toHaveCount(2);
});

test('keeps the initial focus and produces no audio during play', async ({ page }) => {
  let audioRequests = 0;
  page.on('request', (request) => {
    if (request.resourceType() === 'media') audioRequests += 1;
  });
  await page.goto(GAME_URL);
  expect(
    await page.locator('button:focus, select:focus, input:focus, textarea:focus').count(),
  ).toBe(0);
  await page.addInitScript(() => {
    for (const key of ['AudioContext', 'webkitAudioContext', 'Audio']) {
      Object.defineProperty(window, key, {
        configurable: true,
        value: class {
          constructor() {
            throw new Error('Unexpected synthesized audio');
          }
        },
      });
    }
    HTMLMediaElement.prototype.play = () => {
      throw new Error('Unexpected media playback');
    };
    speechSynthesis.speak = () => {
      throw new Error('Unexpected synthesized speech');
    };
  });
  await loadFixedBoard(page);
  await finishBoard(page);
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('audio, video')).toHaveCount(0);
  expect(audioRequests).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard, exportedSnapshot, finishBoard, loadFixedBoard } from './game-fixture.ts';
import { PREFERENCES_KEY } from '../src/game/session/storage.ts';

test('better equal and worse completed scores persist after each reload', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  for (const [misses, expected] of [
    [2, 10],
    [1, 9],
    [1, 9],
    [3, 9],
  ]) {
    if (misses === undefined || expected === undefined) throw new Error('Missing score case');
    await page.locator('summary').click();
    await page.getByLabel(ReproductionControl.board, { exact: true }).fill('np1-4-1');
    await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
    await page.locator('summary').click();
    for (let miss = 0; miss < misses; miss++) {
      await page.locator('.card').nth(0).click();
      await page.locator('.card').nth(1).click();
      await page.clock.runFor(800);
    }
    for (const pair of EXAMPLE_PAIRS)
      for (const index of pair) await page.locator('.card').nth(index).click();
    await expect(page.locator('.stats dd').nth(3)).toHaveText(String(expected));
    await page.reload();
    await expect(page.locator('.stats dd').nth(3)).toHaveText(String(expected));
    expect(await exportedSnapshot(page)).toMatchObject({
      matched: [],
      moves: 0,
      elapsedMs: 0,
      started: false,
      selection: { kind: 'closed' },
    });
  }
});

test('snapshot loads save only a valid size and every reload starts fresh', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('summary').click();
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  const valid = {
    version: 1,
    boardCode: 'np1-6-1',
    matched: [],
    moves: 0,
    elapsedMs: 2000,
    started: true,
    selection: { kind: 'one', index: 5 },
  };
  await field.fill(JSON.stringify(valid));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  await page.reload();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
  expect(await exportedSnapshot(page)).toMatchObject({
    matched: [],
    moves: 0,
    elapsedMs: 0,
    started: false,
    selection: { kind: 'closed' },
  });
  await page.locator('summary').click();
  await field.fill(JSON.stringify({ ...valid, boardCode: 'np1-8-1', extra: true }));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.reload();
  await expect(page.getByLabel(DealControl.size, { exact: true })).toHaveValue('6');
});

test('saved size and per-size completed bests survive reload and resets', async ({
  page,
  gameURL,
}) => {
  await loadFixedBoard(page, gameURL);
  await finishBoard(page);
  await page.getByRole('button', { name: DealControl.newGame, exact: true }).click();
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption('6');
  await page.reload();
  await expect(page.locator('.card')).toHaveCount(36);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption('4');
  expect(Number(await page.locator('.stats dd').nth(3).textContent())).toBe(8);
});

test('valid board loads save their size while invalid loads keep that preference', async ({
  page,
  gameURL,
}) => {
  await loadFixedBoard(page, gameURL);
  await page.locator('summary').click();
  const input = page.getByLabel(ReproductionControl.board, { exact: true });
  await input.fill('np1-6-1');
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await input.fill('invalid');
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await page.reload();
  await expect(page.locator('.card')).toHaveCount(36);
});

test('malformed stored preferences fall back to a playable default game', async ({
  page,
  gameURL,
}) => {
  await page.addInitScript((key) => localStorage.setItem(key, '{'), PREFERENCES_KEY);
  await page.goto(gameURL);
  await expect(page.locator('.card')).toHaveCount(16);
});

